const items = $input.all();
const total = items.length;

let leftCount = 0;
let stayedCount = 0;

const byDepartment = {};
const byOverTime = {};
const byMaritalStatus = {};
const byJobRole = {};
const byBusinessTravel = {};
const byGender = {};
const byJobLevel = {};
const byStockOption = {};
const byJobSatisfaction = {};
const byWorkLifeBalance = {};
const byAgeGroup = {};
const byYearsAtCompany = {};
const byIncomeGroup = {};

let totalIncomeLeavers = 0;
let totalIncomeStayers = 0;
let totalAgeLeavers = 0;
let totalAgeStayers = 0;
let totalYearsLeavers = 0;
let totalYearsStayers = 0;

function incrementGroup(group, key, attrition) {
  if (!group[key]) group[key] = { total: 0, left: 0 };
  group[key].total++;
  if (attrition === 'Yes') group[key].left++;
}

function ageGroup(age) {
  if (age < 25) return '18-24';
  if (age < 35) return '25-34';
  if (age < 45) return '35-44';
  if (age < 55) return '45-54';
  return '55+';
}

function yearsGroup(y) {
  if (y === 0) return '0';
  if (y <= 2) return '1-2';
  if (y <= 5) return '3-5';
  if (y <= 10) return '6-10';
  return '10+';
}

function incomeGroup(income) {
  if (income < 3000) return '<3000';
  if (income < 6000) return '3000-5999';
  if (income < 10000) return '6000-9999';
  if (income < 15000) return '10000-14999';
  return '15000+';
}

for (const item of items) {
  const r = item.json;
  const attrition = r.Attrition;
  const isLeft = attrition === 'Yes';

  if (isLeft) leftCount++; else stayedCount++;

  incrementGroup(byDepartment, r.Department, attrition);
  incrementGroup(byOverTime, r.OverTime, attrition);
  incrementGroup(byMaritalStatus, r.MaritalStatus, attrition);
  incrementGroup(byJobRole, r.JobRole, attrition);
  incrementGroup(byBusinessTravel, r.BusinessTravel, attrition);
  incrementGroup(byGender, r.Gender, attrition);
  incrementGroup(byJobLevel, 'Level ' + r.JobLevel, attrition);
  incrementGroup(byStockOption, 'Level ' + r.StockOptionLevel, attrition);
  incrementGroup(byJobSatisfaction, 'Level ' + r.JobSatisfaction, attrition);
  incrementGroup(byWorkLifeBalance, 'Level ' + r.WorkLifeBalance, attrition);
  incrementGroup(byAgeGroup, ageGroup(Number(r.Age)), attrition);
  incrementGroup(byYearsAtCompany, yearsGroup(Number(r.YearsAtCompany)), attrition);
  incrementGroup(byIncomeGroup, incomeGroup(Number(r.MonthlyIncome)), attrition);

  const income = Number(r.MonthlyIncome);
  const age = Number(r.Age);
  const years = Number(r.YearsAtCompany);

  if (isLeft) {
    totalIncomeLeavers += income;
    totalAgeLeavers += age;
    totalYearsLeavers += years;
  } else {
    totalIncomeStayers += income;
    totalAgeStayers += age;
    totalYearsStayers += years;
  }
}

function formatGroup(group) {
  const result = {};
  for (const key in group) {
    const g = group[key];
    result[key] = {
      total: g.total,
      left: g.left,
      attritionRate: ((g.left / g.total) * 100).toFixed(1) + '%'
    };
  }
  return result;
}

return [{
  json: {
    summary: {
      totalEmployees: total,
      left: leftCount,
      stayed: stayedCount,
      overallAttritionRate: ((leftCount / total) * 100).toFixed(1) + '%'
    },
    averages: {
      incomeLeavers: Math.round(totalIncomeLeavers / leftCount),
      incomeStayers: Math.round(totalIncomeStayers / stayedCount),
      ageLeavers: (totalAgeLeavers / leftCount).toFixed(1),
      ageStayers: (totalAgeStayers / stayedCount).toFixed(1),
      yearsLeavers: (totalYearsLeavers / leftCount).toFixed(1),
      yearsStayers: (totalYearsStayers / stayedCount).toFixed(1)
    },
    byDepartment: formatGroup(byDepartment),
    byOverTime: formatGroup(byOverTime),
    byMaritalStatus: formatGroup(byMaritalStatus),
    byJobRole: formatGroup(byJobRole),
    byBusinessTravel: formatGroup(byBusinessTravel),
    byGender: formatGroup(byGender),
    byJobLevel: formatGroup(byJobLevel),
    byStockOption: formatGroup(byStockOption),
    byJobSatisfaction: formatGroup(byJobSatisfaction),
    byWorkLifeBalance: formatGroup(byWorkLifeBalance),
    byAgeGroup: formatGroup(byAgeGroup),
    byYearsAtCompany: formatGroup(byYearsAtCompany),
    byIncomeGroup: formatGroup(byIncomeGroup)
  }
}];

const item = $input.first().json;
const markdown = item.text || '';

const stats = $('PrepareStats').first().json;

function mdToHtml(md) {
  let html = md;

  // Заголовки
  html = html.replace(/^### (.*)$/gm, '<h3>$1</h3>');
  html = html.replace(/^## (.*)$/gm, '<h2>$1</h2>');
  html = html.replace(/^# (.*)$/gm, '<h1>$1</h1>');

  // Жирный текст
  html = html.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');

  // Курсив
  html = html.replace(/\*(.+?)\*/g, '<em>$1</em>');

  // Списки
  html = html.replace(/^- (.*)$/gm, '<li>$1</li>');
  html = html.replace(/(<li>.*<\/li>\n?)+/g, '<ul>$&</ul>');

  // Переносы строк
  html = html.replace(/\n\n/g, '</p><p>');
  html = '<p>' + html + '</p>';

  return html;
}

const reportHtml = mdToHtml(markdown);

const fullHtml = `
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<style>
  body { font-family: Arial, sans-serif; color: #222; line-height: 1.6; max-width: 800px; margin: 20px auto; }
  h1 { color: #1a4d7a; border-bottom: 3px solid #1a4d7a; padding-bottom: 8px; }
  h2 { color: #2c6ea8; margin-top: 28px; border-bottom: 1px solid #ddd; padding-bottom: 6px; }
  h3 { color: #444; margin-top: 20px; }
  strong { color: #000; }
  ul { margin: 10px 0; padding-left: 20px; }
  li { margin-bottom: 6px; }
  p { margin: 10px 0; }
  .meta { background: #f5f8fa; border-left: 4px solid #1a4d7a; padding: 12px 16px; margin: 20px 0; }
</style>
</head>
<body>
  <div class="meta">
    <strong>HR Analytics: анализ оттока сотрудников</strong><br>
    Всего сотрудников: ${stats.summary.totalEmployees} |
    Ушло: ${stats.summary.left} |
    Осталось: ${stats.summary.stayed} |
    Процент оттока: ${stats.summary.overallAttritionRate}
  </div>
  ${reportHtml}
  <p style="color: #888; font-size: 12px; margin-top: 40px;">
    Отчёт сгенерирован автоматически на основе IBM HR Analytics dataset.
  </p>
</body>
</html>
`;

return [{
  json: {
    html: fullHtml,
    rawMarkdown: markdown,
    totalEmployees: stats.summary.totalEmployees,
    left: stats.summary.left,
    attritionRate: stats.summary.overallAttritionRate
  }
}];
